# Check locale definitions for month-related strings
from arrow.locales import EnglishLocale
eng = EnglishLocale()

# Look for month-related format strings
for attr in dir(eng):
    if not attr.startswith('_'):
        val = getattr(eng, attr)
        if isinstance(val, str) and ('month' in attr.lower()):
            print(f"{attr}: {repr(val)}")
